    [/^Showing your roadmap, courses and applications saved on (.+)\. Steps you tick now are kept and sync when you are back online\.$/, d => `${d} मा सेभ भएका तपाईंका मार्गचित्र, पाठ्यक्रम र आवेदन देखाइँदैछ। अहिले चिनो लगाएका चरण सुरक्षित रहन्छन् र अनलाइन भएपछि सिंक हुन्छन्।`],
    [/^Employers see you as Candidate (\w+) until they select you\.$/, c => `छनोट नगरेसम्म रोजगारदाताले तपाईंलाई उम्मेदवार ${c} भनेर देख्छन्।`]
